// ── Load ──────────────────────────────────────────────────────────────────────
var loadAll=j.useCallback(function(){
  setLoading(true);
  Promise.all([
    api("/calls").then(function(r){return r.ok?r.json():[];}),
    api("/agents").then(function(r){return r.ok?r.json():[];}),
    api("/connectors").then(function(r){return r.ok?r.json():[];}),
    api("/settings").then(function(r){return r.ok?r.json():{};}),
    api("/calls/stats").then(function(r){return r.ok?r.json():{};})
  ]).then(function(D){
    setCalls(D[0]||[]);setAgents(D[1]||[]);setConns(D[2]||[]);
    var s=D[3]||{};setSettings(s);setSWh(s.webhook_url||"");
    setStats(D[4]||{});setLoading(false);
  }).catch(function(){setLoading(false);});
},[]);
j.useEffect(function(){loadAll();},[]);
j.useEffect(function(){
  if(!stats.active)return;
  var t=setInterval(function(){
    api("/calls/stats").then(function(r){return r.ok?r.json():null;}).then(function(s){if(s)setStats(s);});
    api("/calls").then(function(r){return r.ok?r.json():null;}).then(function(d){if(d)setCalls(d);});
  },8000);
  return function(){clearInterval(t);};
},[stats.active]);

// ── Actions ───────────────────────────────────────────────────────────────────
function placeCall(){
  if(!cPhone||!cGoal){setCMsg({t:"err",m:"Phone and goal required"});return;}
  setCBusy(true);setCMsg({t:"info",m:"Initiating call via CALL-E..."});
  api("/calls",{method:"POST",body:JSON.stringify({phone:cPhone,goal:cGoal,agentId:cAgent?parseInt(cAgent):undefined,voice:cVoice,provider:cProv})})
    .then(function(r){return r.json();})
    .then(function(d){
      if(d.error){setCMsg({t:"err",m:d.error});setCBusy(false);return;}
      setCMsg({t:"ok",m:d.warning||"Call initiated"});
      setCPhone("");setCGoal("");setCAgent("");setCBusy(false);
      setTimeout(function(){setShowCallForm(false);setCMsg(null);},1800);
      loadAll();
    }).catch(function(e){setCMsg({t:"err",m:""+e.message});setCBusy(false);});
}
function saveAgent(){
  if(!aN)return;setAS(true);
  var body=JSON.stringify({name:aN,useCase:aU,systemPrompt:aP,voice:aV});
  var p=editAid?api("/agents/"+editAid,{method:"PUT",body:body}):api("/agents",{method:"POST",body:body});
  p.then(function(r){return r.json();}).then(function(){setShowAF(false);setEditAid(null);setAN("");setAP("");setAU("customer-service");setAS(false);loadAll();}).catch(function(){setAS(false);});
}
function delAgent(id){api("/agents/"+id,{method:"DELETE"}).then(loadAll);}
function delCall(id){api("/calls/"+id,{method:"DELETE"}).then(loadAll);}
function clearCalls(){api("/calls",{method:"DELETE"}).then(loadAll);}
function delConn(id){api("/connectors/"+id,{method:"DELETE"}).then(loadAll);}
function openWizard(){setWizStep(1);setWN("");setWU("");setWI("custom");setWScan(null);setWLogs([]);setWPerms([]);setWBusy(false);}
function closeWizard(){setWizStep(0);}

// Wizard: run real scan
function runScan(){
  if(!wN||!wU){return;}
  setWizStep(2);setWLogs([]);setWScan(null);
  // Animated pre-scan logs
  var preSteps=[
    "Connecting to "+wU+"...",
    "Checking SSL certificate...",
    "Detecting framework...",
    "Scanning for OpenAPI spec...",
    "Looking for MCP server...",
    "Checking sitemap & knowledge...",
    "Building business profile..."
  ];
  var idx=0;
  var timer=setInterval(function(){
    if(idx<preSteps.length){
      setWLogs(function(prev){return prev.concat([{ok:null,msg:preSteps[idx]}]);});
      idx++;
    } else {
      clearInterval(timer);
    }
  },600);
  // Real API scan
  api("/connectors/scan",{method:"POST",body:JSON.stringify({websiteUrl:wU,industry:wI})})
    .then(function(r){return r.ok?r.json():r.json().then(function(d){throw new Error(d.error||"Scan failed");});})
    .then(function(data){
      clearInterval(timer);
      setWScan(data);
      setWLogs(data.scanLogs||[]);
      setWPerms(data.capabilities||[]);
      setWVerToken(data.verification_token||"");
      setWVerified(null);
      setTimeout(function(){setWizStep(3);},800);
    })
    .catch(function(e){
      clearInterval(timer);
      setWLogs(function(prev){return prev.concat([{ok:false,msg:"Scan error: "+e.message}]);});
      // Stay on step 2 — do not invent fake capabilities
      setWScan({reachable:false,capabilities:[],systems:[],readiness_score:0,scanLogs:[]});
      setWPerms([]);
    });
}

// Wizard: save connector
function connectBusiness(){
  if(!wN)return;
  setWBusy(true);
  var body={
    name:wN, websiteUrl:wU, industry:wI,
    capabilities:wPerms,
    systems:(wScan&&wScan.systems)||[],
    framework:(wScan&&wScan.framework)||null,
    readiness_score:(wScan&&wScan.readiness_score)||0,
    openAPIUrl:(wScan&&wScan.openAPIUrl)||null,
    verification_token:wVerToken||null,
    verified:wVerified===true,
  };
  api("/connectors",{method:"POST",body:JSON.stringify(body)})
    .then(function(r){return r.json();})
    .then(function(){setWBusy(false);setWizStep(0);loadAll();})
    .catch(function(){setWBusy(false);});
}

function saveSettings(){
  var body={webhookUrl:sWh};
  if(sK)body.calleApiKey=sK;
  api("/settings",{method:"PUT",body:JSON.stringify(body)})
    .then(function(r){return r.json();})
    .then(function(d){setSettings(d);setSK("");setSSaved(true);setTimeout(function(){setSSaved(false);},2500);});
}

